"""Standalone script: answer a single prompt using Llama 3 8B Instruct.

Usage:
    python ask_llama.py "What is the capital of France?"
    python ask_llama.py --max-new-tokens 512 --temperature 0.7 "Write a haiku about the sea."
    echo "Summarize the theory of relativity." | python ask_llama.py
"""

from __future__ import annotations

import argparse
import sys

import torch
from transformers import AutoModelForCausalLM, AutoTokenizer
from typer import prompt

MODEL_ID = "meta-llama/Meta-Llama-3.1-8B-Instruct"
DEFAULT_CONTEXT_LENGTH = 8192
MIN_NEW_TOKENS = 128


def get_context_length(model) -> int:
    """Best-effort lookup of the model's max position/context length."""
    for attribute in ("max_position_embeddings", "n_positions", "seq_length"):
        value = getattr(model.config, attribute, None)
        if isinstance(value, int) and value > 0:
            return value
    return DEFAULT_CONTEXT_LENGTH


def get_terminator_ids(tokenizer) -> list[int]:
    """Return every token ID that should end generation.

    Llama-3 Instruct ends a turn with <|eot_id|>, but tokenizer.eos_token_id
    typically resolves to <|end_of_text|> instead. Passing both as stop
    tokens prevents the model from running on past the real answer.
    """
    terminators = [tokenizer.eos_token_id]
    eot_id = tokenizer.convert_tokens_to_ids("<|eot_id|>")
    if eot_id is not None and eot_id != tokenizer.unk_token_id:
        terminators.append(eot_id)
    return list(dict.fromkeys(t for t in terminators if t is not None))


def ask_llama(prompt: str, *, max_new_tokens: int, temperature: float) -> str:
    tokenizer = AutoTokenizer.from_pretrained(MODEL_ID, trust_remote_code=True)
    if tokenizer.pad_token_id is None:
        tokenizer.pad_token = tokenizer.eos_token

    model = AutoModelForCausalLM.from_pretrained(
        MODEL_ID,
        device_map="auto",
        torch_dtype=torch.bfloat16,
        trust_remote_code=True,
        low_cpu_mem_usage=True,
    )
    model.eval()
    model.generation_config.max_length = None

    messages = [{"role": "user", "content": prompt}]
    inputs = tokenizer.apply_chat_template(
        messages,
        add_generation_prompt=True,
        return_tensors="pt",
        return_dict=True,
    )
    inputs = {key: value.to(model.device) for key, value in inputs.items()}
    prompt_length = inputs["input_ids"].shape[1]

    context_length = get_context_length(model)
    available = context_length - prompt_length
    if available < MIN_NEW_TOKENS:
        print(
            f"Warning: prompt uses {prompt_length} tokens, leaving only "
            f"{available} of {context_length} for the answer.",
            file=sys.stderr,
        )
    effective_max_new_tokens = max(1, min(max_new_tokens, available))

    generation_options = {
        "max_new_tokens": effective_max_new_tokens,
        "do_sample": temperature > 0,
        "pad_token_id": tokenizer.pad_token_id,
        "eos_token_id": get_terminator_ids(tokenizer),
    }
    if temperature > 0:
        generation_options["temperature"] = temperature

    with torch.inference_mode():
        output = model.generate(**inputs, **generation_options)

    generated = output[0, prompt_length:]
    return tokenizer.decode(
        generated,
        skip_special_tokens=True,
        clean_up_tokenization_spaces=False,
    ).strip()


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Ask Llama 3 8B Instruct a single prompt.")
    parser.add_argument("prompt", nargs="?", help="Prompt text. If omitted, read from stdin.")
    parser.add_argument("--max-new-tokens", type=int, default=2048)
    parser.add_argument("--temperature", type=float, default=1.0)
    return parser.parse_args()


